"use client";

import React, { useState } from "react";
import { 
  Calendar as CalendarIcon, 
  MapPin, 
  ChevronRight, 
  Download, 
  Filter, 
  Globe,
  Star
} from "lucide-react";

/* --- 1. INTELLIGENT DATA ARCHITECTURE --- */
const holidays = [
  { name: "Republic Day", date: "Jan 26, 2026", day: "Monday", type: "National", region: "India", description: "Constitution Day celebrations." },
  { name: "Holi", date: "Mar 3, 2026", day: "Tuesday", type: "Public", region: "North/West India", description: "Spring festival of colors." },
  { name: "Good Friday", date: "Apr 3, 2026", day: "Friday", type: "Public", region: "Global", description: "Observed globally." },
  { name: "Independence Day", date: "Aug 15, 2026", day: "Saturday", type: "National", region: "India", description: "Commemorating sovereignty." },
  { name: "Diwali", date: "Nov 8, 2026", day: "Sunday", type: "Public", region: "Global", description: "Victory of light over darkness." },
  { name: "Christmas Day", date: "Dec 25, 2026", day: "Thursday", type: "Public", region: "Global", description: "Annual holiday." },
];

export default function PremiumHolidayHub() {
  const [activeFilter, setActiveFilter] = useState("All");

  const filteredHolidays = holidays.filter(h => 
    activeFilter === "All" || h.type === activeFilter || h.region === activeFilter
  );

  return (
    <div className="min-h-screen bg-[#F8F9FB] dark:bg-[#020408] p-6 lg:p-12 space-y-10 font-sans">
      
      {/* 1. HEADER: THE SPOTLIGHT */}
      <div className="flex flex-col lg:flex-row justify-between items-end gap-8 border-b border-gray-200 dark:border-gray-800 pb-10">
        <div className="space-y-4">
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-brand-500 animate-pulse" />
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-400">Time Governance</span>
          </div>
          <h1 className="text-5xl font-black tracking-tighter text-gray-900 dark:text-white uppercase italic">
            Annual <span className="text-gray-400 font-medium not-italic">Holidays</span>
          </h1>
          <p className="text-sm text-gray-500 max-w-md font-medium">
            Strategic downtime planning for the 2026 fiscal year across global and regional centers.
          </p>
        </div>

        <div className="flex items-center gap-4">
          <button className="flex items-center gap-2 bg-white dark:bg-gray-900 border border-gray-100 dark:border-gray-800 px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:border-brand-500 transition-all shadow-sm">
            <Download size={14} /> Sync Calendar
          </button>
        </div>
      </div>

      {/* 2. PREMIUM FILTER STRIP */}
      <div className="flex items-center justify-between gap-4">
        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
          {["All", "National", "Public", "India", "Global"].map((cat) => (
            <button
              key={cat}
              onClick={() => setActiveFilter(cat)}
              className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                activeFilter === cat 
                ? "bg-gray-900 text-white dark:bg-brand-600 shadow-xl shadow-brand-500/20 scale-105" 
                : "bg-white dark:bg-gray-900 text-gray-400 border border-gray-100 dark:border-gray-800 hover:text-gray-900"
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
        <div className="hidden md:flex items-center gap-2 text-[10px] font-black uppercase text-gray-400">
          <Filter size={14} /> Filter Logic
        </div>
      </div>

      {/* 3. THE TIMELINE LAYOUT */}
      <div className="grid grid-cols-1 gap-4">
        {filteredHolidays.map((holiday, index) => (
          <div 
            key={index}
            className="group relative flex items-center justify-between p-6 bg-white dark:bg-gray-900 rounded-[2.5rem] border border-gray-100 dark:border-gray-800 transition-all hover:border-brand-500/30 hover:shadow-2xl hover:shadow-brand-500/5 overflow-hidden"
          >
            {/* Visual Flair */}
            <div className="absolute -right-10 -bottom-10 w-32 h-32 bg-gray-50 dark:bg-gray-800/50 rounded-full group-hover:bg-brand-500/5 transition-all duration-700" />
            
            <div className="flex items-center gap-8 z-10">
              {/* Chrono-Badge */}
              <div className="flex flex-col items-center justify-center w-20 h-20 bg-gray-50 dark:bg-gray-800 rounded-3xl border border-gray-100 dark:border-gray-700/50 group-hover:bg-brand-600 group-hover:border-brand-600 transition-all duration-500">
                <span className="text-[10px] font-black text-gray-400 group-hover:text-brand-100 uppercase">{holiday.date.split(' ')[0]}</span>
                <span className="text-2xl font-black text-gray-900 dark:text-white group-hover:text-white leading-none mt-1">
                    {holiday.date.split(' ')[1].replace(',', '')}
                </span>
              </div>

              {/* Identity */}
              <div>
                <div className="flex items-center gap-2 mb-1">
                    <span className={`text-[8px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md ${
                        holiday.type === 'National' ? 'bg-purple-500/10 text-purple-500' : 'bg-brand-500/10 text-brand-500'
                    }`}>
                        {holiday.type}
                    </span>
                    {index === 0 && (
                        <span className="flex items-center gap-1 text-[8px] font-black text-emerald-500 uppercase tracking-widest">
                            <Star size={10} fill="currentColor" /> Upcoming Next
                        </span>
                    )}
                </div>
                <h3 className="text-xl font-black tracking-tight text-gray-900 dark:text-white uppercase italic group-hover:translate-x-1 transition-transform">
                  {holiday.name}
                </h3>
                <div className="flex items-center gap-4 mt-2">
                  <div className="flex items-center gap-1 text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                    <MapPin size={12} className="text-brand-500" /> {holiday.region}
                  </div>
                  <div className="w-1 h-1 rounded-full bg-gray-300" />
                  <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{holiday.day}</span>
                </div>
              </div>
            </div>

            {/* Actions */}
            <div className="flex items-center gap-6 z-10">
              <div className="hidden lg:block text-right">
                <p className="text-[10px] font-black text-gray-300 uppercase tracking-widest mb-1">Impact Status</p>
                <p className="text-xs font-bold text-gray-900 dark:text-gray-300 italic">Full Ops Shutdown</p>
              </div>
              <div className="w-12 h-12 rounded-2xl bg-gray-50 dark:bg-gray-800 flex items-center justify-center text-gray-300 group-hover:text-brand-500 group-hover:bg-brand-50 dark:group-hover:bg-brand-500/10 transition-all">
                <ChevronRight size={20} />
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* 4. FOOTER NOTE */}
      <div className="bg-gray-900 dark:bg-brand-600 rounded-[2rem] p-8 text-white flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
        <Globe className="absolute -left-4 -bottom-4 w-32 h-32 opacity-10" />
        <div className="relative z-10">
          <h4 className="text-lg font-black tracking-tighter uppercase italic">Regional Policy Note</h4>
          <p className="text-xs font-medium text-brand-100 max-w-xl mt-2 leading-relaxed uppercase tracking-widest">
            Holidays are subject to regional labor laws. Optional holidays must be requested 48 hours in advance via the Leave Management portal.
          </p>
        </div>
        <button className="relative z-10 bg-white text-gray-900 px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:scale-105 transition-transform">
          Apply For Leave
        </button>
      </div>
    </div>
  );
}